-- Director interview/positioning dictionaries. Repeatable and non-destructive.
INSERT INTO system_dict_type (name, type, status, remark, creator, create_time, updater, update_time, deleted)
SELECT seed.name, seed.type, 0, 'ZSJOS 编导 Demo 表单字典；管理员可维护', 'V129', NOW(), 'V129', NOW(), b'0'
FROM (
 SELECT '编导证书' name,'zsjos_director_certificate' type UNION ALL SELECT '证书实操能力','zsjos_certificate_practice' UNION ALL SELECT '性别','zsjos_gender' UNION ALL SELECT '视频能力','zsjos_video_skill' UNION ALL SELECT '直播经验','zsjos_live_experience' UNION ALL SELECT '拍摄设备','zsjos_shooting_equipment' UNION ALL SELECT '自媒体时间投入','zsjos_media_time' UNION ALL SELECT '出镜意愿','zsjos_appearance_willingness' UNION ALL SELECT '购买动机','zsjos_purchase_motivation' UNION ALL SELECT '交付风险','zsjos_delivery_risk' UNION ALL SELECT '核心身份标签','zsjos_identity_tag' UNION ALL SELECT '现有素材清单','zsjos_position_material' UNION ALL SELECT '定位时间投入','zsjos_time_investment' UNION ALL SELECT '表达能力','zsjos_expression_ability' UNION ALL SELECT '执行稳定性','zsjos_execution_stability' UNION ALL SELECT '定位风险标注','zsjos_position_risk' UNION ALL SELECT '人设类型','zsjos_persona_type' UNION ALL SELECT '目标人群','zsjos_target_audience' UNION ALL SELECT '内容支柱','zsjos_content_pillar' UNION ALL SELECT '视频内容形式','zsjos_video_format' UNION ALL SELECT '图文内容形式','zsjos_image_text_format' UNION ALL SELECT '布尔选择','zsjos_boolean_choice'
) seed WHERE NOT EXISTS (SELECT 1 FROM system_dict_type x WHERE x.type=seed.type AND x.deleted=b'0');

INSERT INTO system_dict_data (sort,label,value,dict_type,status,color_type,creator,create_time,updater,update_time,deleted)
SELECT seed.sort,seed.label,seed.value,seed.dict_type,0,'default','V129',NOW(),'V129',NOW(),b'0'
FROM (
 SELECT 10 sort,'营养师' label,'nutritionist' value,'zsjos_director_certificate' dict_type UNION ALL SELECT 20,'健康管理师','health_manager','zsjos_director_certificate' UNION ALL SELECT 30,'心理咨询师','psychological','zsjos_director_certificate' UNION ALL SELECT 40,'执业药师','licensed_pharmacist','zsjos_director_certificate' UNION ALL SELECT 50,'中医适宜技术','tcm_technique','zsjos_director_certificate' UNION ALL SELECT 60,'康复理疗','rehabilitation','zsjos_director_certificate' UNION ALL SELECT 70,'暂无','none','zsjos_director_certificate'
 UNION ALL SELECT 10,'有实操能力（可配餐/接个案）','practical','zsjos_certificate_practice' UNION ALL SELECT 20,'仅理论、无实操','theory_only','zsjos_certificate_practice'
 UNION ALL SELECT 10,'男','male','zsjos_gender' UNION ALL SELECT 20,'女','female','zsjos_gender'
 UNION ALL SELECT 10,'会','yes','zsjos_video_skill' UNION ALL SELECT 20,'不会','no','zsjos_video_skill'
 UNION ALL SELECT 10,'做过直播','experienced','zsjos_live_experience' UNION ALL SELECT 20,'没做过','none','zsjos_live_experience'
 UNION ALL SELECT 10,'相机','camera','zsjos_shooting_equipment' UNION ALL SELECT 20,'手机','phone','zsjos_shooting_equipment' UNION ALL SELECT 30,'三脚架','tripod','zsjos_shooting_equipment' UNION ALL SELECT 40,'收音麦','microphone','zsjos_shooting_equipment' UNION ALL SELECT 50,'补光灯','light','zsjos_shooting_equipment' UNION ALL SELECT 60,'暂无设备','none','zsjos_shooting_equipment'
 UNION ALL SELECT 10,'A（8h+/周）','high','zsjos_media_time' UNION ALL SELECT 20,'B（4-8h/周）','medium','zsjos_media_time' UNION ALL SELECT 30,'C（<4h/周）','low','zsjos_media_time'
 UNION ALL SELECT 10,'愿意出镜','willing','zsjos_appearance_willingness' UNION ALL SELECT 20,'条件式出镜','conditional','zsjos_appearance_willingness' UNION ALL SELECT 30,'不愿意','unwilling','zsjos_appearance_willingness'
 UNION ALL SELECT 10,'副业','side_business','zsjos_purchase_motivation' UNION ALL SELECT 20,'获客能力','customer_acquisition','zsjos_purchase_motivation' UNION ALL SELECT 30,'考证咨询','exam_consulting','zsjos_purchase_motivation' UNION ALL SELECT 40,'IP','ip','zsjos_purchase_motivation' UNION ALL SELECT 50,'技能实操','practical_skill','zsjos_purchase_motivation' UNION ALL SELECT 60,'其他','other','zsjos_purchase_motivation'
