 UNION ALL SELECT 10,'专业背书型','professional','zsjos_identity_tag' UNION ALL SELECT 20,'学习成长型','learning_growth','zsjos_identity_tag' UNION ALL SELECT 30,'家庭实践型','family_practice','zsjos_identity_tag' UNION ALL SELECT 40,'职业转型型','career_transition','zsjos_identity_tag' UNION ALL SELECT 50,'技能实操型','skill_practice','zsjos_identity_tag' UNION ALL SELECT 60,'政策咨询型','policy_consulting','zsjos_identity_tag'
 UNION ALL SELECT 10,'学习笔记','study_notes','zsjos_position_material' UNION ALL SELECT 20,'实操视频','practice_video','zsjos_position_material' UNION ALL SELECT 30,'职业场景','work_scene','zsjos_position_material' UNION ALL SELECT 40,'家庭场景','family_scene','zsjos_position_material' UNION ALL SELECT 50,'备考记录','exam_record','zsjos_position_material' UNION ALL SELECT 60,'群聊截图','chat_screenshot','zsjos_position_material' UNION ALL SELECT 70,'课程页面','course_page','zsjos_position_material' UNION ALL SELECT 80,'打卡记录','checkin_record','zsjos_position_material'
 UNION ALL SELECT 10,'A（8h+）','high','zsjos_time_investment' UNION ALL SELECT 20,'B（4-8h）','medium','zsjos_time_investment' UNION ALL SELECT 30,'C（<4h）','low','zsjos_time_investment'
