 UNION ALL SELECT 10,'学习笔记','study_notes','zsjos_content_pillar' UNION ALL SELECT 20,'备考打卡','exam_checkin','zsjos_content_pillar' UNION ALL SELECT 30,'个人故事','personal_story','zsjos_content_pillar' UNION ALL SELECT 40,'实操练习','practice','zsjos_content_pillar' UNION ALL SELECT 50,'职业经验','career_experience','zsjos_content_pillar' UNION ALL SELECT 60,'报考问答','exam_qa','zsjos_content_pillar' UNION ALL SELECT 70,'轻创过程','light_process','zsjos_content_pillar' UNION ALL SELECT 80,'场景问题','scene_problem','zsjos_content_pillar' UNION ALL SELECT 90,'专业观点','professional_view','zsjos_content_pillar' UNION ALL SELECT 100,'品牌故事','brand_story','zsjos_content_pillar' UNION ALL SELECT 110,'考试避坑','exam_pitfall','zsjos_content_pillar'
 UNION ALL SELECT 10,'口播','talking_head','zsjos_video_format' UNION ALL SELECT 20,'vlog','vlog','zsjos_video_format' UNION ALL SELECT 30,'实拍','live_shoot','zsjos_video_format' UNION ALL SELECT 40,'剧情','drama','zsjos_video_format' UNION ALL SELECT 50,'混剪','mixed_edit','zsjos_video_format'
 UNION ALL SELECT 10,'学员实拍','student_photo','zsjos_image_text_format' UNION ALL SELECT 20,'设计','design','zsjos_image_text_format'
 UNION ALL SELECT 10,'是','yes','zsjos_boolean_choice' UNION ALL SELECT 20,'否','no','zsjos_boolean_choice'
) seed WHERE NOT EXISTS (SELECT 1 FROM system_dict_data x WHERE x.dict_type=seed.dict_type AND x.value=seed.value AND x.deleted=b'0');

INSERT INTO zsjos_schema_version (version, description, checksum, installed_at)
SELECT 'V129','seed director form dictionaries',SHA2('V129__seed_director_form_dictionaries.sql',256),NOW()
WHERE NOT EXISTS (SELECT 1 FROM zsjos_schema_version WHERE version='V129');
